import type { BiomarkerInput, DrugInput, EntityInput, PaperInput, PathwayInput, TargetInput, TechnologyInput, TermInput, TrialInput } from "@/lib/schema";
import type { Spike, SpikeSupplement } from "./index";

/**
 * COLORECTAL CANCER, MOLECULAR LAYER. Facts checked 2026-09-24.
 *
 * The genomic landscape as a sourced table (`colorectalMolecularLandscape`), sidedness as biology rather than anatomy
 * (`colorectalSidedness`), the two routes to a carcinoma (`colorectalRoutes`: the adenoma-carcinoma sequence and the
 * serrated pathway, with the driver order each imposes), the consensus molecular subtypes and the older TCGA classes
 * (`colorectalSubtypes`), the immune microenvironment and why mismatch repair deficiency responds to checkpoint
 * blockade while microsatellite-stable disease does not (`colorectalImmune`), circulating tumour DNA for minimal
 * residual disease with its trial evidence and its limits (`colorectalCtdna`), and the pathways, biomarker readouts,
 * targets, tests and medicines that follow; plus paper records for every landscape paper cited.
 *
 * Sources and rules. Every frequency names its cohort, its size and the paper it was read from. Figures marked
 * "cBioPortal" were computed on 24 September 2026 from the public cBioPortal API (read-only) on the named study id:
 * the count of samples carrying a non-synonymous mutation (or a high-level amplification or deep deletion in the
 * discrete copy-number profile, or a structural variant) over the study's sequenced sample list. They are
 * sample-level frequencies for the study as deposited, not the paper's own percentages, which are quoted alongside
 * where an abstract gives them. KRAS and BRAF allele shares are counts of mutation records over all mutation records
 * for that gene in the study, so a tumour with two mutations in one gene counts twice. Panel cohorts (MSK-IMPACT,
 * ChangKang) do not bait every gene: ACVR2A, BCL9L, RSPO2 and CDX2 read zero there because they are absent from the
 * panel, not from the disease. Nothing is invented and no OncoKB or COSMIC data was used. Abstract text was read from
 * Europe PMC.
 *
 * Cancer id. The corpus cancer record is `colorectal` (src/data/cancers.ts, patched by spikes/colorectal.ts); this
 * file patches it too. Every reference goes through COLORECTAL_CANCER_ID.
 *
 * Terms and trials are not created here (the owner's brief for this layer); the report lists the ones the layer would
 * link to.
 */
export const COLORECTAL_CANCER_ID = "colorectal";
const CRC = COLORECTAL_CANCER_ID;
const asOf = "2026-09-24";

const doi = (d: string) => `https://doi.org/${d}`;
const pubmed = (pmid: string) => `https://pubmed.ncbi.nlm.nih.gov/${pmid}/`;
const cbio = (study: string) => `https://www.cbioportal.org/study/summary?id=${study}`;

type P = Omit<PaperInput, "kind" | "asOf">;
const p = (x: P): PaperInput => ({ kind: "paper", asOf, ...x });
/** A partial record for an entity another file owns; arrays append, scalars fill gaps only (see applySpikeSupplements). */
const sup = <T extends EntityInput>(x: { id: string } & Partial<Omit<T, "id" | "kind">>): SpikeSupplement => x as SpikeSupplement;

