// ======================= SIDEDNESS AS BIOLOGY =======================
/**
 * Left and right are not two halves of one organ. The midgut (caecum to the proximal two-thirds of the transverse
 * colon) and the hindgut (distal transverse colon to the rectum) have different embryological origins, blood
 * supplies, microbiota and epithelial programmes, and the tumours that arise in them differ in almost every
 * molecular feature that has been measured. `share` gives the measured split; `outcome` gives what it changes.
 */
export const colorectalSidedness: Array<{ feature: string; share: string; outcome: string; sources: Array<{ label: string; url: string }> }> = [
  { feature: "Microsatellite instability", share: "221 of 908 right-sided against 134 of 2,575 left-sided samples, 24.3% against 5.2%, in crc_msk_2026; 65 of 341 against 39 of 779, 19.1% against 5.0%, in crc_msk_2017; 27 of 79 against 1 of 144 in coadread_tcga_pub; 58 of 320 against 18 of 695 in crc_sysucc_2022 (cBioPortal; the crc_msk_2026 count uses the 3,483 samples with a named subsite, 908 right and 2,575 left).",
    outcome: "The whole immunotherapy population of colorectal cancer sits disproportionately on the right, which is also part of why right-sided disease looks worse in first-line metastatic trials and better in resected stage II disease.",
    sources: [CBIO_MSK2026, CBIO_MSK2017, CBIO_TCGA2012, CBIO_SYSUCC] },
  { feature: "BRAF V600E", share: "174 of 908 right-sided against 75 of 2,575 left-sided samples, 19.2% against 2.9%, in crc_msk_2026; 60 of 341 against 25 of 779, 17.6% against 3.2%, in crc_msk_2017; 18 of 79 against 2 of 144 in coadread_tcga_pub (cBioPortal). Within the right side the rate climbs from 10% at the caecum to 22% at the hepatic flexure (Loree 2018).",
    outcome: "BRAF V600E is the single biggest reason right-sided metastatic disease does worse; in the pooled CAIRO, CAIRO2, COIN and FOCUS analysis the overall survival hazard ratio for BRAF mutation was 1.91 and the poor prognosis of deficient mismatch repair disappeared once BRAF was accounted for (Venderbosch 2014).",
    sources: [CBIO_MSK2026, CBIO_MSK2017, CBIO_TCGA2012, link(SRC.loree2018), link(SRC.venderbosch2014)] },
  { feature: "KRAS and PIK3CA", share: "KRAS 471 of 908 right-sided against 1,023 of 2,575 left-sided, 51.9% against 39.7%; PIK3CA 294 of 908 against 398 of 2,575, 32.4% against 15.5% (crc_msk_2026, cBioPortal). Right-sided RAS mutation itself falls from 70% at the caecum to 43% at the hepatic flexure (Loree 2018).",
    outcome: "Right-sided microsatellite-stable tumours were enriched for oncogenic KRAS, BRAF, PIK3CA, AKT1, RNF43 and SMAD4 alterations, while left-sided tumours frequently had no identifiable mitogenic driver at all and instead expressed more mitogenic ligand, which is the mechanistic reading of why EGFR antibodies work on the left (Yaeger 2018).",
    sources: [CBIO_MSK2026, link(SRC.loree2018), link(SRC.yaeger2018)] },
  { feature: "APC and TP53", share: "APC 1,998 of 2,575 left-sided against 590 of 908 right-sided, 77.6% against 65.0%; TP53 2,039 of 2,575 against 515 of 908, 79.2% against 56.7% (crc_msk_2026, cBioPortal); the same direction in crc_msk_2017 (APC 81.5% against 65.4%, TP53 79.2% against 58.7%).",
    outcome: "The classical adenoma-carcinoma sequence with chromosomal instability is a left-sided description; distal tumours are more chromosome-unstable and more often EGFR or HER2 amplified with epiregulin overexpression, proximal ones more mucinous, MSI-high and BRAF-like with a serrated expression signature (Missiaglia 2014).",
    sources: [CBIO_MSK2026, CBIO_MSK2017, link(SRC.missiaglia2014)] },
  { feature: "EGFR antibody benefit (the predictive effect)", share: "2,159 of the 5,760 patients in CRYSTAL, FIRE-3, CALGB 80405, PRIME, PEAK and 20050181 had both primary tumour location and RAS status recorded: 515 right-sided and 1,644 left-sided (Arnold 2017).",
    outcome: "Chemotherapy plus an EGFR antibody improved survival in left-sided tumours (overall survival hazard ratio 0.75, progression-free survival 0.78) and did not in right-sided tumours (1.12 and 1.12), with interaction p less than 0.001 and 0.002 (Arnold 2017). The same interaction appears in each of CRYSTAL (hazard ratio 1.95) and FIRE-3 (0.40) separately (Tejpar 2017). This is the only place in colorectal oncology where an anatomical fact is used as a predictive biomarker.",
    sources: [link(SRC.arnold2017), link(SRC.tejpar2017)] },
  { feature: "Prognosis independent of treatment", share: "Right against left in RAS wild-type metastatic disease: overall survival hazard ratio 2.03 in the pooled control arms and 1.38 in the pooled experimental arms; progression-free survival 1.59 and 1.25; objective response odds ratio 0.38 and 0.56 (Arnold 2017).",
    outcome: "Right-sided stage III colon cancer also had much worse survival after relapse (hazard ratio 1.95) even after adjusting for BRAF status, while the risk of relapse itself did not differ by side (Missiaglia 2014).",
    sources: [link(SRC.arnold2017), link(SRC.missiaglia2014)] },
  { feature: "Where the line should be drawn", share: "Across 1,876 patients, mutation prevalence varied within each side as much as between them; the sigmoid and rectal region had more TP53, less PIK3CA, BRAF and CTNNB1 mutation and less microsatellite instability than the rest of the left colon, and transverse colon tumours clustered with the left by mutation profile even though they are conventionally called right (Loree 2018).",
    outcome: "A left-right split at the splenic flexure still maximised the prognostic separation, so the convention survives, but the consensus molecular subtypes shift continuously along the bowel: CMS1 and CMS3 fall and CMS2 rises moving distally (Loree 2018).",
    sources: [link(SRC.loree2018)] },
];

// ======================= THE ROUTES TO A CARCINOMA =======================
export const colorectalRoutes: Array<{ route: string; precursor: string; drivers: string; sequence: string; sources: Array<{ label: string; url: string }> }> = [
  { route: "Adenoma-carcinoma sequence (conventional, chromosomal instability)",
    precursor: "Tubular and tubulovillous adenoma, then advanced adenoma with high-grade dysplasia, then invasive carcinoma. Mostly left-sided.",
    drivers: "APC first (WNT), then KRAS, then 18q and SMAD4, then 17p and TP53. The order came from measuring four alterations across the stages in 172 specimens: ras mutations were in 58% of adenomas larger than 1 cm but only 9% of adenomas under 1 cm; chromosome 5q sequences were lost in 29 to 35% of adenomas and carcinomas; an 18q region was lost in 73% of carcinomas, 47% of advanced adenomas and 11 to 13% of earlier adenomas; and 17p loss was almost confined to carcinomas at 75% (Vogelstein 1988). The model was set out the following year as a sequence in which the total accumulation of alterations matters more than the order of any one step (Fearon and Vogelstein 1990).",
    sequence: "What has changed since. WNT activation is now known to be near-universal rather than usual: 93% of tumours in the TCGA analysis (Cancer Genome Atlas Network 2012) and 96% once intronic APC splice alterations and large in-frame CTNNB1 deletions are counted (Yaeger 2018), with RNF43, AXIN2 and RSPO fusions accounting for most of the APC-wild-type remainder (Seshagiri 2012). Chromosomal instability was shown to be a distinct, dominant and continuing cellular defect rather than a by-product, running at more than 10^-2 chromosome gains or losses per cell division (Lengauer 1997). And the sequence starts before any lesion: whole-genome sequencing of hundreds of normal crypts from 42 people found probable driver mutations in about 1% of morphologically normal crypts in middle age, so adenomas and carcinomas are rare outcomes of a pervasive process across the whole epithelium (Lee-Six 2019).",
    sources: [link(SRC.vogelstein1988), link(SRC.fearon1990), link(SRC.tcga2012), link(SRC.yaeger2018), link(SRC.seshagiri2012), link(SRC.lengauer1997), link(SRC.leeSix2019)] },
  { route: "Serrated pathway",
    precursor: "Microvesicular hyperplastic polyp, then sessile serrated lesion (formerly sessile serrated adenoma), then sessile serrated lesion with cytological dysplasia, then carcinoma; separately the traditional serrated adenoma. Sessile serrated lesions are proximal, traditional serrated adenomas distal. About 30% of colorectal carcinomas develop this way, serrated-class polyps are found in 20 to 40% of average-risk people, and sessile serrated lesions in up to 15% when the endoscopist looks carefully (Bettington 2013, Crockett and Nagtegaal 2019).",
    drivers: "BRAF V600E or KRAS first, not APC, and then methylation rather than chromosome loss. The consistent abnormality is CpG island methylation, of low or high degree, with activating BRAF or KRAS mutation; that gives three classes, BRAF-mutant CIMP-high MSI-high, BRAF-mutant CIMP-high microsatellite stable, and KRAS-mutant CIMP-low microsatellite stable (Bettington 2013). WNT disruption arrives later and more often through RNF43 than APC (Crockett and Nagtegaal 2019), which matches the RNF43 frameshift sitting in 491 of 770 MSI-high against 241 of 6,447 microsatellite-stable samples in crc_msk_2026 (cBioPortal).",
    sequence: "The methylation step is the clinically decisive one: CIMP-positive tumours are a genuinely distinct subset that encompasses almost all BRAF-mutant cancers (odds ratio 203, from 195 methylation markers across 295 tumours and 16,785 quantitative analyses), and sporadic mismatch repair deficiency occurs almost exclusively as a consequence of CIMP-associated MLH1 methylation (Weisenberger 2006), which silences MLH1 reversibly and restores repair capacity when the methylation is removed (Herman 1998). CIMP-high was 95 of 500 assessable tumours, 19%, in the prospective exome cohort (cBioPortal coadread_dfci_2016). Cytological dysplasia in a sessile serrated lesion signals advanced genetic abnormality and a high risk of progression, and progression is fast once it appears, which is why serrated polyps drive interval cancers and shorter surveillance intervals (Bettington 2013, Crockett and Nagtegaal 2019).",
    sources: [link(SRC.bettington2013), link(SRC.crockett2019), link(SRC.weisenberger2006), link(SRC.herman1998), CBIO_MSK2026, CBIO_DFCI] },
  { route: "Lynch syndrome (the inherited short cut)",
    precursor: "Conventional adenoma, but reaching carcinoma in a few years rather than a decade because mismatch repair fails at the adenoma stage.",
    drivers: "A germline pathogenic variant in MLH1, MSH2, MSH6 or PMS2, or a 3' EPCAM deletion whose read-through transcription methylates the MSH2 promoter in cis, silencing it in EpCAM-expressing tissue only (Ligtenberg 2009); the second hit is somatic. Downstream, repair failure drives frameshifts in coding microsatellites: TGFBR2 was the first identified, mutated in 8 of the first MSI colon cancer lines examined, clustered in short repeats, with no surface receptor left (Markowitz 1995), and ACVR2A, RNF43 and B2M follow the same mechanism.",
    sequence: "Finding the carriers is a testing problem rather than a biology problem: among 10,206 colorectal cancer probands, 312 (3.1%) carried a mismatch repair gene mutation, and testing every tumour found 100% of them against 87.8% for the Bethesda guidelines and 85.4% for the Jerusalem recommendations, at the cost of testing about a third more tumours (Moreira 2012). The guideline route is mismatch repair immunohistochemistry or MSI testing on every colorectal cancer, then BRAF V600E or MLH1 methylation to separate the sporadic MLH1-silenced cases from Lynch syndrome (Sepulveda 2017).",
    sources: [link(SRC.ligtenberg2009), link(SRC.markowitz1995), link(SRC.moreira2012), link(SRC.sepulveda2017)] },
  { route: "Polymerase proofreading (POLE and POLD1)",
    precursor: "Multiple or large adenomas and early-onset carcinoma in the germline form; no distinctive precursor in the somatic form.",
    drivers: "A mutation in the exonuclease (proofreading) domain of DNA polymerase epsilon or delta, so misincorporated bases are never corrected. Germline POLE p.Leu424Val and POLD1 p.Ser478Asn are high-penetrance predisposition variants found in multiple-adenoma and early-onset colorectal cancer families and in no controls, with POLD1 also predisposing to endometrial cancer (Palles 2013). Somatic exonuclease-domain mutations produce the same phenotype in 1.0% of colorectal cancers (Domingo 2016).",
    sequence: "The tumours are ultramutated but microsatellite stable, so a mismatch repair panel and an MSI assay both read normal: median tumour mutational burden 172.1 per megabase in the 52 hotspot cases in crc_msk_2026, against 5.7 in microsatellite-stable and 56.9 in MSI-high tumours (cBioPortal). POLE mutation and mismatch repair deficiency were mutually exclusive (none of 66 against 833 of 6,211), POLE-mutant patients were younger (median 54.5 against 67.2 years) and more often male, the tumours carried CD8 infiltration and cytotoxic marker expression as high as MSI-high disease, and the recurrence hazard ratio was 0.34 (Domingo 2016). They are the reason sequencing has a place alongside immunohistochemistry even when the repair panel is intact.",
    sources: [link(SRC.palles2013), link(SRC.domingo2016), CBIO_MSK2026] },
];

// ======================= SUBTYPES =======================
export const colorectalSubtypes: Array<{ scheme: string; subtype: string; share: string; biology: string; therapy: string; sources: Array<{ label: string; url: string }> }> = [
  { scheme: "TCGA (2012)", subtype: "Hypermutated versus non-hypermutated", share: "16% of 276 tumours were hypermutated: three-quarters of those had the expected high microsatellite instability, usually with hypermethylation and MLH1 silencing, and one-quarter had somatic mismatch repair gene or POLE mutations. In the deposit, MSI-high reads 38 of 276 and MSI-low 44 (Cancer Genome Atlas Network 2012; cBioPortal coadread_tcga_pub).",
    biology: "Once the hypermutated cancers are excluded, colon and rectal tumours have considerably similar patterns of genomic alteration, which is the empirical basis for treating them as one molecular disease with two anatomies. Twenty-four genes were significantly mutated, adding ARID1A, SOX9 and FAM123B to the expected APC, TP53, SMAD4, PIK3CA and KRAS; recurrent amplifications included ERBB2 and, newly, IGF2; a NAV2-TCF7L1 fusion was found; and integrative analysis pointed to MYC-directed transcriptional activation and repression as the common output (Cancer Genome Atlas Network 2012).",
    therapy: "This is the split that decides immunotherapy: the hypermutated sixth is where checkpoint blockade works and the other five-sixths is where it does not.",
    sources: [link(SRC.tcga2012), CBIO_TCGA2012] },
  { scheme: "Consensus molecular subtypes (Guinney 2015)", subtype: "CMS1 immune, CMS2 canonical, CMS3 metabolic, CMS4 mesenchymal", share: "Four robust classes agreed by six independent classification systems across 4,151 samples, with about 13% of tumours falling between them (Guinney 2015).",
    biology: "CMS1 (about 14%) is the MSI-immune class: hypermutated, BRAF-mutant, right-sided, strongly infiltrated. CMS2 (about 37%) is canonical: epithelial, WNT and MYC activated, chromosomally unstable, left-sided. CMS3 (about 13%) is metabolic: KRAS-enriched with metabolic dysregulation. CMS4 (about 23%) is mesenchymal: TGF-beta activated, stroma-rich, angiogenic, with the worst relapse-free and overall survival (Guinney 2015).",
    therapy: "In the only randomised test, on 581 primary tumours from CALGB/SWOG 80405, the subtypes were prognostic for overall and progression-free survival (p less than 0.001) and predictive (interaction p less than 0.001 for overall survival): CMS1 patients lived longer on bevacizumab than on cetuximab (p less than 0.001) and CMS2 patients longer on cetuximab than on bevacizumab (p = 0.0046) (Lenz 2019). No guideline uses the classification and no assay is approved for it; calling it needs bulk RNA, which is the practical reason it has not reached the clinic.",
    sources: [link(SRC.guinney2015), link(SRC.lenz2019)] },
  { scheme: "What CMS4 actually measures (Isella and Calon, 2015)", subtype: "The mesenchymal signal is stromal, not epithelial", share: "Two papers published back to back in the same issue.",
    biology: "Species-specific expression analysis of patient-derived xenografts, where human cancer cells grow in mouse stroma, showed that the mesenchymal transcripts of the poor-prognosis subtype come from the mouse (stromal) compartment, and that signatures built to report cancer-associated fibroblasts, leukocytes or endothelial cells were all significantly higher in those human tumours (Isella 2015). The parallel paper found that the predictive power of every published classification arose from genes expressed by stromal rather than epithelial cells, identified stromal markers that associated robustly with relapse, and showed that fibroblasts increase the frequency of tumour-initiating cells, an effect dramatically enhanced by TGF-beta (Calon 2015).",
    therapy: "High fibroblast signature expression was associated with poor prognosis in untreated disease, and joint high expression of the stromal signatures predicted resistance to radiotherapy in rectal cancer; blocking TGF-beta between cancer cells and the microenvironment halted progression in organoids and xenografts (Isella 2015, Calon 2015). It is also why a CMS4 call on bulk RNA says as much about how much stroma was in the block as about the cancer cells.",
    sources: [link(SRC.isella2015), link(SRC.calon2015)] },
  { scheme: "Location as a continuum (Loree 2018)", subtype: "Subsite rather than side", share: "Mutation prevalence in 1,876 patients and consensus molecular subtype in a separate cohort of 608.",
    biology: "TP53, KRAS, BRAF V600, PIK3CA, SMAD4, CTNNB1, GNAS and PTEN mutation rates all differ by precise subsite, and the variation within each side is as large as the variation between sides; CMS1 and CMS3 decline and CMS2 rises moving distally (Loree 2018).",
    therapy: "The practical reading is that side is a crude proxy that happens to maximise prognostic separation, and that the sigmoid-rectal region and the transverse colon are the two places where the proxy breaks down.",
    sources: [link(SRC.loree2018)] },
];

// ======================= IMMUNE MICROENVIRONMENT =======================
export const colorectalImmune: Array<{ feature: string; finding: string; implication: string; sources: Array<{ label: string; url: string }> }> = [
  { feature: "Why mismatch repair deficiency responds", finding: "Whole-exome sequencing gave a mean of 1,782 somatic mutations per mismatch repair deficient tumour against 73 per proficient tumour, and the difference translated directly into response: pembrolizumab produced an immune-related objective response in 4 of 10 deficient colorectal cancers and 0 of 18 proficient ones, with 20-week immune-related progression-free survival of 78% against 11% (Le 2015). Extending the same test to 12 tumour types gave objective responses in 53% and complete responses in 21%, and led to the first tissue-agnostic approval (Le 2017).",
    implication: "Mismatch repair status, not the organ, selects the drug. First-line pembrolizumab doubled progression-free survival over chemotherapy in MSI-high metastatic disease (16.5 against 8.2 months, hazard ratio 0.60) in KEYNOTE-177; single-agent nivolumab gave 23 objective responses in 74 previously treated patients (31.1%) with disease control for 12 weeks or longer in 69% (Overman 2017); four weeks of neoadjuvant nivolumab plus ipilimumab produced pathological complete response in 68% of locally advanced dMMR colon cancers (NICHE-2); and in dMMR rectal cancer dostarlimab alone has produced clinical complete responses without surgery or radiation (Cercek 2022).",
    sources: [link(SRC.le2015), link(SRC.le2017), link(SRC.keynote177), link(SRC.overman2017), link(SRC.niche2), link(SRC.cercek2022)] },
  { feature: "Why microsatellite-stable disease does not", finding: "The proficient arm of the first pembrolizumab study had 0 of 18 responses (Le 2015). IMblaze370 then tested the idea at phase 3 scale in 363 previously treated patients: median overall survival was 8.87 months with atezolizumab plus cobimetinib, 7.10 with atezolizumab alone and 8.51 with regorafenib, hazard ratios 1.00 and 1.19 against regorafenib (Eng 2019). Microsatellite-stable tumours carry a median of 5.7 mutations per megabase against 56.9 in MSI-high tumours (crc_msk_2026, cBioPortal).",
    implication: "Low mutation load is the necessary but not the sufficient reason. Mice carrying all four main colorectal mutations in intestinal stem cells developed metastatic tumours with the hallmarks of human microsatellite-stable disease, including low mutational burden, T-cell exclusion and TGF-beta-activated stroma, and PD-1 or PD-L1 blockade did little; inhibiting TGF-beta unleashed a potent and enduring cytotoxic T-cell response that prevented metastasis and made established liver metastases susceptible to checkpoint blockade (Tauriello 2018). Activated WNT signalling was independently correlated with the absence of T-cell infiltration across 1,211 tumours (Grasso 2018).",
    sources: [link(SRC.le2015), link(SRC.eng2019), CBIO_MSK2026, link(SRC.tauriello2018), link(SRC.grasso2018)] },
  { feature: "Immunoediting inside the responsive group", finding: "MSI-high tumours frequently break the antigen-presentation machinery: B2M is mutated in 239 of 770 MSI-high against 95 of 6,447 microsatellite-stable samples in crc_msk_2026 and 27 of 105 against 10 of 702 in crc_msk_2017 (cBioPortal), with biallelic B2M and HLA losses by copy-number change and copy-neutral loss of heterozygosity documented across 1,211 tumours (Grasso 2018). Positive selection of mutations in HLA genes and other antigen-processing components was found specifically in lymphocyte-rich tumours (Giannakis 2016).",
    implication: "It is the best available explanation for the third of MSI-high patients who do not respond to a checkpoint inhibitor, and the reason B2M status is now read off sequencing reports rather than treated as noise.",
    sources: [CBIO_MSK2026, CBIO_MSK2017, link(SRC.grasso2018), link(SRC.giannakis2016)] },
  { feature: "The immune infiltrate as a measurement in its own right", finding: "The type, density and location of T cells in a colorectal tumour predicted outcome better than stage (Galon 2006); the consensus Immunoscore, a digital count of CD3 and CD8 cells in the tumour and its invasive margin, was validated internationally across 14 centres in 13 countries in 2,681 stage I-III patients, where a high score carried a hazard ratio of 0.20 for time to recurrence against a low score, independently of age, sex, T stage, N stage and microsatellite instability (Pages 2018). In an integrative analysis, Immunoscore predicted disease-specific recurrence and survival better than microsatellite status (Mlecnik 2016).",
    implication: "Immune status is prognostic across the whole disease, not only in the hypermutated sixth, and a subgroup of microsatellite-stable tumours carries a prominent immune expression programme. No approval uses Immunoscore; it is used in research and in some European centres.",
    sources: [link(SRC.galon2006), link(SRC.pages2018), link(SRC.mlecnik2016)] },
  { feature: "Making microsatellite-stable disease respond", finding: "The one combination with an unambiguous signal is an Fc-enhanced CTLA-4 antibody with a PD-1 antibody: botensilimab plus balstilimab gave an objective response rate of 17% (17 of 101 response-evaluable patients) and disease control in 61% among 148 heavily pre-treated microsatellite-stable patients, with median progression-free survival of 3.5 months and a median duration of response not reached (Bullock 2024).",
    implication: "That is the highest response rate reported with immunotherapy alone in microsatellite-stable colorectal cancer, but it comes from a single-arm phase 1 with treatment-related adverse events in 89% and a 12% discontinuation rate, and the randomised confirmation has not reported. TGF-beta blockade, WNT inhibition and vaccines are the other routes under test, each following from the mechanisms above.",
    sources: [link(SRC.bullock2024), link(SRC.tauriello2018)] },
];

// ======================= ctDNA AND MINIMAL RESIDUAL DISEASE =======================
export const colorectalCtdna: Array<{ question: string; evidence: string; limit: string; sources: Array<{ label: string; url: string }> }> = [
  { question: "Does circulating tumour DNA after surgery predict recurrence?",
    evidence: "In 230 patients with resected stage II colon cancer, among those given no adjuvant chemotherapy ctDNA was detectable after surgery in 14 of 178 (7.9%) and 11 of those 14 (79%) recurred, against 16 of 164 (9.8%) of the ctDNA-negative patients, a hazard ratio of 18 (Tie 2016). In 130 stage I-III patients with 829 serial plasma samples, ctDNA was detectable before surgery in 108 of 122 (88.5%); positivity at day 30 gave a recurrence hazard ratio of 7.2, positivity shortly after adjuvant chemotherapy 17.5 (all 7 such patients relapsed), and positivity during surveillance 43.5, with lead times over standard imaging of up to 16.5 months (Reinert 2019). In 168 stage III patients with 1,204 samples the postoperative hazard ratio was 7.0 and the post-chemotherapy hazard ratio 50.8, with a median lead time of 9.8 months (Henriksen 2022). In 1,039 prospectively followed patients, week-4 positivity carried a recurrence hazard ratio of 10.0 and 18-month disease-free survival of 38.4% against 90.5% (Kotani 2023).",
    limit: "A negative result is not a cure: 16 of 164 ctDNA-negative stage II patients still recurred (Tie 2016), and sensitivity falls with tumour volume, with lung-only and peritoneal recurrence the classic blind spots.",
    sources: [link(SRC.tie2016), link(SRC.reinert2019), link(SRC.henriksen2022), link(SRC.galaxy2023)] },
  { question: "Can it be used to withhold chemotherapy?",
    evidence: "DYNAMIC randomised 455 patients with resected stage II colon cancer 2:1 to ctDNA-guided or standard management. Adjuvant chemotherapy was given to 15% against 28%, and two-year recurrence-free survival was 93.5% against 92.4%, meeting non-inferiority (Tie 2022). It is the only randomised evidence that a ctDNA result can safely change a treatment decision in this disease.",
    limit: "It shows de-escalation is safe in stage II; it does not show that treating a ctDNA-positive patient improves survival, and the non-inferiority margin was 8.5 percentage points with two years of follow-up. Escalation is the question still open.",
    sources: [link(SRC.dynamic2022)] },
  { question: "Does treating a positive result help?",
    evidence: "In GALAXY, adjuvant chemotherapy was associated with much better disease-free survival among ctDNA-positive patients (hazard ratio 6.59) and not among negative ones, and clearance during treatment predicted good outcomes (Kotani 2023). In IMPROVE-IT only patients who cleared ctDNA permanently during adjuvant chemotherapy avoided relapse, 16 of 20 postoperatively positive patients relapsed despite treatment, and serial measurement separated slow growth (25% increase a month) from fast (143% a month), with the growth rate itself prognostic for survival (Henriksen 2022).",
    limit: "Both are observational: treatment was not randomised, so the benefit estimate is confounded by who was offered chemotherapy. The randomised escalation trials are the ones that will answer it.",
    sources: [link(SRC.galaxy2023), link(SRC.henriksen2022)] },
  { question: "What else does plasma sequencing do here?",
    evidence: "It reads resistance in real time. KRAS mutant subclones appeared in the serum of 9 of 24 patients whose tumours were KRAS wild-type before panitumumab, generally 5 to 6 months into treatment, and mathematical modelling placed those clones in the tumour before therapy began (Diaz 2012); secondary KRAS mutations or amplification were found in 6 of 10 patients progressing on an EGFR antibody, with mutant alleles detectable in blood as much as 10 months before radiographic progression (Misale 2012). Plasma genotyping can also select treatment: TRIUMPH enrolled on HER2 amplification confirmed in tissue or in ctDNA and gave a confirmed response rate of 30% in 27 tissue-positive and 28% in 25 ctDNA-positive patients, against 0% in a matched real-world salvage population (Nakamura 2021).",
    limit: "Plasma sensitivity depends on tumour fraction, so a negative plasma panel in low-volume disease does not exclude an alteration; tissue remains the reference for the first-line RAS and BRAF result under the ASCP, CAP, AMP and ASCO guideline (Sepulveda 2017).",
    sources: [link(SRC.diaz2012), link(SRC.misale2012), link(SRC.triumph2021), link(SRC.sepulveda2017)] },
];

